begin;
create table public.payment_authorizations(id uuid primary key default gen_random_uuid(),mission_id uuid not null,payment_id uuid not null unique,receipt_id uuid not null unique,provider_authorization_id text not null,order_id text not null,expires_at timestamptz not null,created_at timestamptz not null default clock_timestamp(),unique(mission_id,id),unique(mission_id,provider_authorization_id),foreign key(mission_id,payment_id)references public.payments(mission_id,id),foreign key(mission_id,receipt_id)references public.provider_receipts(mission_id,id));
create table public.authorization_followups(id uuid primary key default gen_random_uuid(),mission_id uuid not null,source_authorization_id uuid not null unique,effect_authorization_id uuid not null unique,action text not null check(action in('payment_authorization_capture','payment_authorization_void')),created_at timestamptz not null default clock_timestamp(),foreign key(mission_id,source_authorization_id)references public.payment_authorizations(mission_id,id),foreign key(mission_id,effect_authorization_id)references public.effect_authorizations(mission_id,id));
create table public.refund_claims(id uuid primary key default gen_random_uuid(),mission_id uuid not null,payment_id uuid not null,effect_authorization_id uuid not null unique,amount_minor bigint not null check(amount_minor>0),created_at timestamptz not null default clock_timestamp(),foreign key(mission_id,payment_id)references public.payments(mission_id,id),foreign key(mission_id,effect_authorization_id)references public.effect_authorizations(mission_id,id));
create table public.authorization_obligations(id uuid primary key default gen_random_uuid(),mission_id uuid not null,payment_authorization_id uuid not null unique references public.payment_authorizations(id),commitment_id uuid not null unique,created_at timestamptz not null default clock_timestamp(),foreign key(mission_id,commitment_id)references public.commitments(mission_id,id));
create table public.voice_confirmation_obligations(id uuid primary key default gen_random_uuid(),session_id uuid not null unique references public.voice_sessions(id),mission_id uuid not null,commitment_id uuid not null unique,created_at timestamptz not null default clock_timestamp(),foreign key(mission_id,commitment_id)references public.commitments(mission_id,id));
create table public.voice_confirmation_drafts(id uuid primary key default gen_random_uuid(),mission_id uuid not null,session_id uuid not null references public.voice_sessions(id),artifact_version_id uuid not null unique,created_at timestamptz not null default clock_timestamp(),foreign key(mission_id,artifact_version_id)references public.artifact_versions(mission_id,id));
create table private.voice_confirmation_payloads(session_id uuid primary key references public.voice_sessions(id),mission_id uuid not null,body_hash text not null check(body_hash~'^[a-f0-9]{64}$'));
do $$declare t text;begin foreach t in array array['payment_authorizations','authorization_followups','refund_claims','authorization_obligations','voice_confirmation_obligations','voice_confirmation_drafts']loop execute format('alter table public.%I enable row level security',t);execute format('alter table public.%I force row level security',t);execute format('create policy mission_scope on public.%I using(private.owns_mission(mission_id))with check(private.owns_mission(mission_id))',t);execute format('create trigger immutable_row before update or delete on public.%I for each row execute function private.immutable_row()',t);execute format('create trigger ledger_revision after insert on public.%I for each row execute function private.record_ledger_revision()',t);execute format('grant select on public.%I to founder_role,lead_role,specialist_role,policy_role',t);end loop;end$$;
-- Authorization expiry is actionable work, not a spent fact. The existing
-- commitment scheduler monitors this exact provider date and escalates overdue
-- work; capture/void still requires its separate founder authorization.
create function private.open_authorization_obligation()returns trigger language plpgsql security definer set search_path=''as $$declare commitment uuid;party uuid;begin
 select payee_id into strict party from public.payments where mission_id=new.mission_id and id=new.payment_id;
 insert into public.commitments(mission_id,party_id,direction,description,due_at,actor_id)values(new.mission_id,party,'outbound','Payment authorised; obtain founder approval to capture or void before the provider authorisation expires.',new.expires_at,private.actor_id())returning id into commitment;
 insert into public.commitment_states(mission_id,commitment_id,status)values(new.mission_id,commitment,'open');
 insert into public.authorization_obligations(mission_id,payment_authorization_id,commitment_id)values(new.mission_id,new.id,commitment);
 insert into public.outbox(mission_id,type,payload)values(new.mission_id,'payment.authorization_due',jsonb_build_object('paymentId',new.payment_id,'commitmentId',commitment,'captureOrVoidBy',new.expires_at));return new;
end$$;
create trigger open_authorization_obligation after insert on public.payment_authorizations for each row execute function private.open_authorization_obligation();
create function private.authorization_obligation_close_guard()returns trigger language plpgsql security definer set search_path=''as $$begin
 if new.status='closed'and exists(select from public.authorization_obligations where mission_id=new.mission_id and commitment_id=new.commitment_id)and not exists(
  select from public.authorization_obligations o join public.payment_authorizations pa on pa.id=o.payment_authorization_id join public.evidence e on e.id=new.closed_by_evidence_id and e.mission_id=o.mission_id and e.kind='payment_authorization_resolved'and e.trust='performed'and e.payload->>'paymentAuthorizationId'=pa.id::text
  join public.payment_states ps on ps.mission_id=o.mission_id and ps.payment_id=pa.payment_id and ps.receipt_id=e.provider_receipt_id
  join public.provider_receipts r on r.id=ps.receipt_id and r.mission_id=o.mission_id
  join public.authorization_followups f on f.source_authorization_id=pa.id and f.effect_authorization_id=r.authorization_id and f.action=r.operation
  where o.mission_id=new.mission_id and o.commitment_id=new.commitment_id and((ps.state='captured'and f.action='payment_authorization_capture'and ps.confirmation_event_id is not null)or(ps.state='failed'and f.action='payment_authorization_void'))
 )then raise exception 'invariant_violation: authorization obligation requires its confirmed capture or actual void receipt';end if;return new;
end$$;
create trigger authorization_obligation_close_guard before insert on public.commitment_states for each row execute function private.authorization_obligation_close_guard();
create function private.complete_authorization_obligation()returns trigger language plpgsql security definer set search_path=''as $$declare item record;fact uuid;begin
 if new.state not in('captured','failed')or new.receipt_id is null then return new;end if;
 for item in select o.commitment_id,pa.id authorization_id from public.authorization_obligations o join public.payment_authorizations pa on pa.id=o.payment_authorization_id join public.authorization_followups f on f.source_authorization_id=pa.id join public.provider_receipts r on r.authorization_id=f.effect_authorization_id and r.operation=f.action where o.mission_id=new.mission_id and pa.payment_id=new.payment_id and r.id=new.receipt_id and((new.state='captured'and f.action='payment_authorization_capture'and new.confirmation_event_id is not null)or(new.state='failed'and f.action='payment_authorization_void'))and not exists(select from public.commitment_states cs where cs.commitment_id=o.commitment_id and cs.status='closed')loop
  fact:=public.append_evidence(new.mission_id,'supply','payment_authorization_resolved','performed',jsonb_build_object('paymentAuthorizationId',item.authorization_id,'paymentId',new.payment_id,'state',new.state),'receipt',new.receipt_id::text,new.receipt_id);perform public.close_commitment(new.mission_id,item.commitment_id,fact);
 end loop;return new;
end$$;
create trigger complete_authorization_obligation after insert on public.payment_states for each row execute function private.complete_authorization_obligation();
revoke all on function private.open_authorization_obligation(),private.authorization_obligation_close_guard(),private.complete_authorization_obligation()from public;
create function private.mandate_exposure(p_mission uuid,p_mandate uuid)returns bigint language sql stable security definer set search_path=''as $$select coalesce(sum(amount_minor),0)from public.effect_authorizations where mission_id=p_mission and mandate_id=p_mandate and intent->>'action'not in('payment_refund','payment_authorization_capture','payment_authorization_void')$$;
create function private.mission_exposure(p_mission uuid)returns bigint language sql stable security definer set search_path=''as $$
 select greatest(0,coalesce((select sum(a.amount_minor)from public.effect_authorizations a where a.mission_id=p_mission and a.intent->>'action'not in('payment_refund','payment_authorization_capture','payment_authorization_void')and not exists(select from public.payments p join public.payment_authorizations pa on pa.payment_id=p.id join public.authorization_followups f on f.source_authorization_id=pa.id and f.action='payment_authorization_void'join public.provider_receipts r on r.authorization_id=f.effect_authorization_id and r.operation='payment_authorization_void'where p.authorization_id=a.id)),0)-coalesce((select sum(amount_minor)from public.money_ledger where mission_id=p_mission and kind='refund'),0))::bigint
$$;
create function private.payment_source(p_mission uuid,p_intent jsonb,p_current uuid default null)returns jsonb language plpgsql stable set search_path=''as $$declare payload jsonb;p public.payments;pa public.payment_authorizations;source_receipt public.provider_receipts;fx public.effect_fx_conversions;q public.fx_quotes;claimed bigint;conversion jsonb;begin
 select coalesce(content->'payload',content)into strict payload from public.artifact_versions where mission_id=p_mission and id=(p_intent->>'artifactVersionId')::uuid;
 if p_intent->>'action'='payment_refund'then
  select payment.*into p from public.payments payment join public.payment_states state on state.payment_id=payment.id and state.state='captured'join public.provider_receipts receipt on receipt.id=state.receipt_id where payment.mission_id=p_mission and receipt.provider='paypal'and receipt.provider_reference=payload->>'captureId'and receipt.data->>'orderId'=payload->>'orderId';select receipt.*into source_receipt from public.payment_states state join public.provider_receipts receipt on receipt.id=state.receipt_id where state.payment_id=p.id and state.state='captured'and receipt.provider_reference=payload->>'captureId'limit 1;
 else
  select*into pa from public.payment_authorizations where mission_id=p_mission and provider_authorization_id=payload->>'authorizationId'and order_id=payload->>'orderId';select*into p from public.payments where mission_id=p_mission and id=pa.payment_id;select*into source_receipt from public.provider_receipts where id=pa.receipt_id;
  if pa.id is null or exists(select from public.authorization_followups f where f.source_authorization_id=pa.id and f.effect_authorization_id is distinct from p_current)then raise exception 'needs_approval: original mission authorization is absent or already assigned';end if;
  if p_intent->>'action'='payment_authorization_capture'then if pa.expires_at<=clock_timestamp()then raise exception 'needs_approval: original authorization expired';end if;perform private.check_version(p_mission,p.artifact_version_id);end if;
 end if;
 if p.id is null or p.provider<>'paypal'or p.payee_id::text is distinct from p_intent->>'counterpartyId'or p.instrument_id::text is distinct from p_intent->>'instrumentId'or p.currency is distinct from payload->>'currency'or p.currency is distinct from coalesce(p_intent->>'currency',payload->>'currency')or p.sandbox_mode is distinct from(p_intent->>'sandboxMode')::boolean or p.sandbox_mode is distinct from(payload->>'sandboxMode')::boolean or p.amount_minor is distinct from(payload->>'amountMinor')::bigint or p.artifact_version_id::text is distinct from payload->>'artifactVersionId'or source_receipt.data->>'payeeMerchantId'is distinct from payload->>'payeeMerchantId'then raise exception 'needs_approval: exact captured or authorized mission payment lineage required';end if;
 if p_intent->>'action'='payment_refund'then select coalesce(sum(amount_minor),0)into claimed from public.refund_claims where payment_id=p.id and effect_authorization_id is distinct from p_current;if(p_intent->>'amountMinor')::bigint<=0 or(p_intent->>'amountMinor')::bigint+claimed>p.amount_minor then raise exception 'needs_approval: refund exceeds original remaining payment';end if;
 elsif p_intent->>'action'='payment_authorization_capture'and(p_intent->>'amountMinor')::bigint is distinct from p.amount_minor then raise exception 'needs_approval: authorization capture must match the held full amount';end if;
 select*into fx from public.effect_fx_conversions where authorization_id=p.authorization_id;select*into q from public.fx_quotes where id=fx.quote_id;
 if q.id is not null and p_intent->>'effectClass'='spend'then conversion:=private.fx_quote_json(q)||jsonb_build_object('missionAmountMinor',private.fx_minor((p_intent->>'amountMinor')::bigint,q.numerator,q.denominator));if payload->'conversion'is distinct from conversion then raise exception 'needs_approval: approved follow-up must display original booked conversion';end if;end if;
 return jsonb_strip_nulls(jsonb_build_object('paymentId',p.id,'sourceAuthorizationId',pa.id,'amountMinor',case when q.id is null then(p_intent->>'amountMinor')::bigint else private.fx_minor((p_intent->>'amountMinor')::bigint,q.numerator,q.denominator)end,'currency',coalesce(fx.mission_currency,p.currency),'quoteId',q.id));
end$$;
create function public.register_payment_authorization(p_mission uuid,p_receipt uuid)returns uuid language plpgsql security definer set search_path=''as $$declare r public.provider_receipts;p uuid;begin
 perform private.require_role(array['policy_role']);perform private.lock_mission(p_mission);select*into strict r from public.provider_receipts where mission_id=p_mission and id=p_receipt and provider='paypal'and operation='payment_capture'and data->>'authorizationId'=provider_reference and data->>'captureId'is null;
 if r.data->>'authorizationExpiresAt'is null then raise exception 'invariant_violation: dated provider authorization receipt required';end if;p:=public.prepare_payment(p_mission,r.authorization_id,'paypal');insert into public.payment_authorizations(mission_id,payment_id,receipt_id,provider_authorization_id,order_id,expires_at)values(p_mission,p,r.id,r.provider_reference,r.data->>'orderId',(r.data->>'authorizationExpiresAt')::timestamptz)on conflict(receipt_id)do nothing;return p;
end$$;
create function public.payment_for_capture(p_mission uuid,p_receipt uuid)returns uuid language plpgsql security definer set search_path=''as $$declare r public.provider_receipts;p uuid;begin
 perform private.require_role(array['policy_role']);perform private.lock_mission(p_mission);select*into strict r from public.provider_receipts where mission_id=p_mission and id=p_receipt and provider='paypal';if r.operation='payment_capture'then return public.prepare_payment(p_mission,r.authorization_id,'paypal');end if;
 select pa.payment_id into strict p from public.authorization_followups f join public.payment_authorizations pa on pa.id=f.source_authorization_id join public.payments payment on payment.id=pa.payment_id where f.mission_id=p_mission and f.effect_authorization_id=r.authorization_id and f.action='payment_authorization_capture'and r.operation=f.action and r.data->>'orderId'=pa.order_id and r.data->>'captureId'=r.provider_reference and(r.data->>'amountMinor')::bigint=payment.amount_minor and r.data->>'currency'=payment.currency and r.sandbox_mode=payment.sandbox_mode;return p;
end$$;

create or replace function public.reserve_effect(p_mission uuid,p_intent jsonb,p_token_hash text default null)returns jsonb language plpgsql security definer set search_path='' as $$
declare v_existing public.effect_authorizations;v_m public.missions;v_mandate public.mandates;v_approval public.approvals;v_hash text;v_binding jsonb;v_id uuid;v_amount bigint;v_used bigint;v_contacts bigint;v_always boolean;v_conversion jsonb;v_actions bigint;v_source jsonb;v_ceiling bigint;begin
  perform private.require_role(array['policy_role']);perform private.lock_mission(p_mission);perform private.active_mission(p_mission);perform private.assert_safe_content(p_intent);
  if not(p_intent?&array['missionId','taskId','action','effectClass','counterpartyId','idempotencyKey','mode','sandboxMode'])or p_intent->>'missionId'<>p_mission::text or length(p_intent->>'idempotencyKey')not between 16 and 256 or p_intent->>'effectClass'not in('communicate','spend','publish','bind')then raise exception 'validation: incomplete effect intent'using errcode='22023';end if;
  v_hash:=encode(public.digest(p_intent::text,'sha256'),'hex');
  select * into v_existing from public.effect_authorizations where mission_id=p_mission and idempotency_key=p_intent->>'idempotencyKey';
  if found then if v_existing.intent_hash<>v_hash then raise exception 'invariant_violation: idempotency intent mismatch';end if;return private.authorization_json(v_existing.id,true);end if;
  select * into strict v_m from public.effective_missions where id=p_mission;
  if (p_intent->>'sandboxMode')::boolean<>v_m.sandbox_mode then raise exception 'invariant_violation: environment mismatch';end if;
  if not exists(select from public.counterparties where id=(p_intent->>'counterpartyId')::uuid and founder_id=v_m.founder_id and not opt_out)then raise exception 'invariant_violation: counterparty denied';end if;
  if p_token_hash is null and p_intent->>'effectClass'='communicate'and(p_intent->>'mode'<>'do'or private.effect_mode(p_mission,p_intent)<>'do')then raise exception 'needs_approval: guide or help mode requires founder approval';end if;
  v_amount:=coalesce((p_intent->>'amountMinor')::bigint,0);
  if v_amount<0 then raise exception 'validation: negative amount'using errcode='22023';end if;
  if p_intent->>'effectClass'='spend' then
    if not(p_intent?&array['amountMinor','currency','artifactVersionId','instrumentId'])or(v_amount=0 and not(v_m.sandbox_mode and p_intent->>'action'='store_test_order')) then raise exception 'validation: spend requires positive amount mission currency artifact and instrument (sandbox store_test_order may be zero)'using errcode='22023';end if;
    if not exists(select from public.founder_accounts a where a.id=(p_intent->>'instrumentId')::uuid and a.founder_id=v_m.founder_id and a.status='connected' and not exists(select from public.account_revocations where account_id=a.id))then raise exception 'invariant_violation: instrument revoked or not founder owned';end if;
  end if;
  perform private.check_version(p_mission,(p_intent->>'artifactVersionId')::uuid);
  if p_intent->>'effectClass'='communicate'and private.effect_mode(p_mission,p_intent)<>'do'and not(p_intent?'artifactVersionId')then raise exception 'needs_approval: Guide or Help requires a reviewed immutable draft';end if;
  if p_intent->>'action'in('payment_refund','payment_authorization_capture','payment_authorization_void')then v_source:=private.payment_source(p_mission,p_intent);v_conversion:=v_source;v_amount:=0;elsif p_intent->>'effectClass'='spend'then v_conversion:=private.fx_for_intent(p_mission,p_intent);v_amount:=(v_conversion->>'amountMinor')::bigint;end if;
  v_always:=p_intent->>'effectClass'in('publish','bind')or p_intent->>'action'=any(array['production_order','agreement','publish','legal_filing','mission_end','final_selection','material_terms','refund','payment_refund','store_publish','place_production_order','sign_agreement','submit_legal_filing','end_mission','place_order','accept_agreement','marketing_publish','registration','mission_pivot']);
  if p_token_hash is not null then
    select * into v_approval from public.approvals where mission_id=p_mission and token_hash=p_token_hash for update;
    v_binding:=jsonb_build_object('action',p_intent->>'action','counterpartyId',p_intent->>'counterpartyId','amountMinor',p_intent->'amountMinor','currency',p_intent->'currency','artifactVersionId',p_intent->'artifactVersionId');
    if v_approval.id is null or v_approval.expires_at<=clock_timestamp()or v_approval.binding<>v_binding or exists(select from public.approval_consumptions where approval_id=v_approval.id)or exists(select from public.approval_invalidations where approval_id=v_approval.id)or exists(select from public.decision_supersessions where previous_id=v_approval.decision_id)or exists(select from public.stale_marks where mission_id=p_mission and node_id=v_approval.decision_id)then raise exception 'needs_approval: invalid expired stale or consumed approval';end if;
  elsif v_always then raise exception 'needs_approval: action always requires approval';
  else
    select * into v_mandate from public.mandates where mission_id=p_mission and id=(p_intent->>'mandateId')::uuid for update;
    if v_mandate.id is null or v_mandate.expires_at<=clock_timestamp()or exists(select from public.mandate_revocations where mandate_id=v_mandate.id)or exists(select from public.decision_supersessions where previous_id=v_mandate.decision_id)or exists(select from public.stale_marks where mission_id=p_mission and node_id=v_mandate.decision_id)then raise exception 'needs_approval: no live mandate';end if;
    if not(v_mandate.scope->'actions'?(p_intent->>'action'))or not(v_mandate.scope->'effectClasses'?(p_intent->>'effectClass'))or not(v_mandate.scope->'counterpartyIds'?(p_intent->>'counterpartyId'))or(p_intent?'channel'and not(v_mandate.scope->'channels'?(p_intent->>'channel')))or(p_intent?'purpose'and not(v_mandate.scope->'purposes'?(p_intent->>'purpose')))or(p_intent?'instrumentId'and not(v_mandate.scope->'instrumentIds'?(p_intent->>'instrumentId')))then raise exception 'needs_approval: outside mandate scope';end if;
    if p_intent->>'effectClass'='spend'and(v_amount>v_mandate.ceiling_per or v_mandate.currency<>v_m.currency)then raise exception 'needs_approval: per action ceiling exceeded';end if;
    select private.mandate_exposure(p_mission,v_mandate.id),count(*)filter(where(intent->>'newContact')::boolean)into v_used,v_contacts from public.effect_authorizations where mandate_id=v_mandate.id;
    if p_intent->>'effectClass'='spend'and v_mandate.scope?'maxActions'then select count(*)into v_actions from public.effect_authorizations where mandate_id=v_mandate.id and intent->>'effectClass'='spend';if v_actions>=(v_mandate.scope->>'maxActions')::bigint then raise exception 'needs_approval: mandate action count exceeded';end if;end if;
    if v_used+v_amount>v_mandate.ceiling_total then raise exception 'needs_approval: total ceiling exceeded';end if;
    if coalesce((p_intent->>'newContact')::boolean,false)and v_contacts>=coalesce((v_mandate.scope->>'maxNewContacts')::integer,0)then raise exception 'needs_approval: contact ceiling exceeded';end if;
  end if;
  -- Approved budget envelopes are independent of payment authorization.
  if p_intent->>'effectClass'='spend'and p_intent->>'action'<>'payment_refund'then v_ceiling:=private.current_budget_ceiling(p_mission);if v_ceiling is not null and v_amount+private.mission_exposure(p_mission)>v_ceiling then raise exception 'needs_approval: current approved budget exceeded';end if;end if;
  insert into public.effect_authorizations(mission_id,intent,intent_hash,idempotency_key,mandate_id,approval_id,amount_minor,sandbox_mode)values(p_mission,p_intent,v_hash,p_intent->>'idempotencyKey',v_mandate.id,v_approval.id,v_amount,v_m.sandbox_mode)returning id into v_id;
  if v_conversion?'quoteId'then insert into public.effect_fx_conversions(mission_id,authorization_id,quote_id,original_amount_minor,original_currency,mission_amount_minor,mission_currency)values(p_mission,v_id,(v_conversion->>'quoteId')::uuid,(p_intent->>'amountMinor')::bigint,p_intent->>'currency',(v_conversion->>'amountMinor')::bigint,v_m.currency);end if;
  if p_intent->>'action'='payment_refund'then insert into public.refund_claims(mission_id,payment_id,effect_authorization_id,amount_minor)values(p_mission,(v_source->>'paymentId')::uuid,v_id,(p_intent->>'amountMinor')::bigint);elsif p_intent->>'action'in('payment_authorization_capture','payment_authorization_void')then insert into public.authorization_followups(mission_id,source_authorization_id,effect_authorization_id,action)values(p_mission,(v_source->>'sourceAuthorizationId')::uuid,v_id,p_intent->>'action');end if;
  if v_approval.id is not null then insert into public.approval_consumptions(mission_id,approval_id,authorization_id)values(p_mission,v_approval.id,v_id);end if;
  insert into public.effect_states(mission_id,authorization_id,status)values(p_mission,v_id,'reserved');
  perform private.audit(p_mission,'planned','Effect authorized and reserved',array[v_id]);return private.authorization_json(v_id,false);
end$$;
create or replace function public.begin_effect(p_mission uuid,p_authorization uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare v_a public.effect_authorizations;v_status text;v_ceiling bigint;v_voice public.voice_sessions;begin
  perform private.require_role(array['policy_role']);perform private.lock_mission(p_mission);perform private.active_mission(p_mission);
  select * into strict v_a from public.effect_authorizations where mission_id=p_mission and id=p_authorization for update;
  select status into v_status from public.effect_states where authorization_id=p_authorization order by created_at desc,id desc limit 1;
  if v_a.mandate_id is not null and(exists(select from public.mandate_revocations where mandate_id=v_a.mandate_id)or exists(select from public.mandates m where m.id=v_a.mandate_id and(m.expires_at<=clock_timestamp()or exists(select from public.decision_supersessions where previous_id=m.decision_id)or exists(select from public.stale_marks where mission_id=p_mission and node_id=m.decision_id))))then raise exception 'invariant_violation: mandate revoked or expired';end if;
  if v_a.approval_id is not null and(exists(select from public.approval_invalidations where approval_id=v_a.approval_id)or exists(select from public.approvals where id=v_a.approval_id and expires_at<=clock_timestamp()))then raise exception 'needs_approval: approval invalidated or expired';end if;
  perform private.check_version(p_mission,(v_a.intent->>'artifactVersionId')::uuid);
  if v_a.intent->>'effectClass'='communicate'and private.effect_mode(p_mission,v_a.intent)<>'do'and(v_a.approval_id is null or not(v_a.intent?'artifactVersionId'))then raise exception 'needs_approval: current Guide or Help requires reviewed draft approval';end if;
  if v_a.intent->>'action'in('payment_refund','payment_authorization_capture','payment_authorization_void')then perform private.payment_source(p_mission,v_a.intent,v_a.id);elsif v_a.intent->>'effectClass'='spend'then perform private.fx_for_intent(p_mission,v_a.intent);end if;
  if v_a.intent->>'effectClass'='spend'and v_a.intent->>'action'<>'payment_refund'then v_ceiling:=private.current_budget_ceiling(p_mission);if v_ceiling is not null and private.mission_exposure(p_mission)>v_ceiling then raise exception 'needs_approval: current approved budget exceeded before dispatch';end if;end if;
  if v_a.intent->>'channel'='voice'then
   select vs.*into strict v_voice from public.voice_sessions vs join private.provider_credentials tc on tc.ref=vs.twilio_ref where vs.mission_id=p_mission and vs.task_id::text=v_a.intent->>'taskId'and vs.counterparty_id::text=v_a.intent->>'counterpartyId'and tc.account_id::text=v_a.intent->>'instrumentId'and exists(select from public.voice_model_budgets b where b.session_id=vs.id)and not exists(select from public.voice_session_events ended where ended.session_id=vs.id and ended.kind='ended');
   perform 1 from public.founder_accounts account join private.provider_credentials credential on credential.account_id=account.id where credential.ref in(v_voice.twilio_ref,v_voice.openai_ref)for share of account;
   if exists(select from public.account_revocations revoked join private.provider_credentials credential on credential.account_id=revoked.account_id where credential.ref in(v_voice.twilio_ref,v_voice.openai_ref))or(v_voice.mandate_id is not null and not exists(select from public.mandates m where m.mission_id=p_mission and m.id=v_voice.mandate_id and m.expires_at>clock_timestamp()and not exists(select from public.mandate_revocations mr where mr.mandate_id=m.id)and exists(select from public.active_decisions d where d.id=m.decision_id and d.mission_id=p_mission)))then raise exception 'needs_approval: current voice accounts and negotiation authority required';end if;
  end if;
  perform 1 from public.founder_accounts where id=(v_a.intent->>'instrumentId')::uuid for share;
  if exists(select from public.account_revocations where account_id=(v_a.intent->>'instrumentId')::uuid)then raise exception 'invariant_violation: instrument revoked';end if;
  if v_status<>'reserved' then return private.authorization_json(p_authorization,true);end if;
  insert into public.effect_states(mission_id,authorization_id,status)values(p_mission,p_authorization,'started');return private.authorization_json(p_authorization,false);
end$$;
create or replace function public.confirm_payment(p_mission uuid,p_payment uuid,p_receipt uuid,p_confirmation uuid)returns uuid language plpgsql security definer set search_path='' as $$declare v_p public.payments;v_id uuid;v_fx public.effect_fx_conversions;v_q public.fx_quotes;begin
  perform private.require_role(array['policy_role']);perform private.lock_mission(p_mission);select * into strict v_p from public.payments where mission_id=p_mission and id=p_payment for update;
  if not exists(select from public.provider_receipts r where r.id=p_receipt and r.mission_id=p_mission and r.sandbox_mode=v_p.sandbox_mode and r.provider=v_p.provider and r.data->>'captureId'=r.provider_reference and r.operation in('payment_capture','payment_authorization_capture')and(r.authorization_id=v_p.authorization_id or exists(select from public.authorization_followups f join public.payment_authorizations pa on pa.id=f.source_authorization_id where f.effect_authorization_id=r.authorization_id and f.action='payment_authorization_capture'and pa.payment_id=v_p.id)))then raise exception 'invariant_violation: payment receipt mismatch';end if;
  if not exists(select from public.events e join public.provider_receipts r on r.id=p_receipt and r.mission_id=e.mission_id where e.id=p_confirmation and e.mission_id=p_mission and e.signature_verified and e.provider=v_p.provider and e.type in('payment.captured','payment.verified_poll')and(e.payload->>'paymentId')=p_payment::text and(e.payload->>'amountMinor')::bigint=v_p.amount_minor and e.payload->>'currency'=v_p.currency and(e.payload->>'sandboxMode')::boolean=v_p.sandbox_mode and e.payload->>'payeeId'=v_p.payee_id::text and e.payload->>'providerReference'=r.provider_reference and e.payload->>'orderId'=r.data->>'orderId'and length(e.payload->>'orderId')>0)then raise exception 'invariant_violation: verified payment confirmation required';end if;
  if exists(select from public.payment_states where payment_id=p_payment and state='captured')then select id into v_id from public.payment_states where payment_id=p_payment and state='captured';return v_id;end if;
  insert into public.payment_states(mission_id,payment_id,state,receipt_id,confirmation_event_id)values(p_mission,p_payment,'captured',p_receipt,p_confirmation)returning id into v_id;
  select*into v_fx from public.effect_fx_conversions where authorization_id=v_p.authorization_id;select*into v_q from public.fx_quotes where id=v_fx.quote_id;
  insert into public.money_ledger(mission_id,kind,amount_minor,currency,basis,envelope,ref_id,receipt_id,confirmation_event_id,sandbox_mode,original_amount_minor,original_currency,fx_quote_id,fx_rate,fx_source,fx_at)values(p_mission,'spent',coalesce(v_fx.mission_amount_minor,v_p.amount_minor),coalesce(v_fx.mission_currency,v_p.currency),'accepted',v_p.purpose,p_payment,p_receipt,p_confirmation,v_p.sandbox_mode,v_p.amount_minor,v_p.currency,v_q.id,v_q.numerator::numeric/v_q.denominator::numeric,v_q.source,v_q.observed_at);
  insert into public.outbox(mission_id,type,payload)values(p_mission,'payment.captured',jsonb_build_object('paymentId',p_payment));return v_id;
end$$;
create function public.register_authorization_void(p_mission uuid,p_receipt uuid)returns uuid language plpgsql security definer set search_path=''as $$declare p uuid;begin perform private.require_role(array['policy_role']);perform private.lock_mission(p_mission);select pa.payment_id into strict p from public.provider_receipts r join public.authorization_followups f on f.effect_authorization_id=r.authorization_id and f.action='payment_authorization_void'join public.payment_authorizations pa on pa.id=f.source_authorization_id where r.mission_id=p_mission and r.id=p_receipt and r.operation=f.action;insert into public.payment_states(mission_id,payment_id,state,receipt_id)select p_mission,p,'failed',p_receipt where not exists(select from public.payment_states where payment_id=p and receipt_id=p_receipt);return p;end$$;
create or replace function public.append_voice_event(p_mission uuid,p_session uuid,p_kind text,p_key text,p_payload jsonb)returns uuid language plpgsql security definer set search_path=''as $$declare v_id uuid;v_commitment uuid;v public.voice_sessions;begin
  perform private.require_role(array['voice_role','ingress_role']);perform private.lock_mission(p_mission);perform private.assert_safe_content(p_payload);select *into strict v from public.voice_sessions where id=p_session and mission_id=p_mission;
  if p_kind in('transcript','fact','stream_started')and exists(select from public.voice_session_events where session_id=p_session and kind='ended')then raise exception 'invariant_violation: ended voice record is frozen';end if;
  if p_kind='transcript'and not v.recording_consent then raise exception 'invariant_violation: transcript retention consent absent';end if;
  if p_kind='stream_started'and not exists(select from public.provider_references where mission_id=p_mission and provider='twilio'and provider_reference=p_payload->>'callSid'and correlation->>'voiceSessionId'=p_session::text)then raise exception 'invariant_violation: voice call correlation mismatch';end if;
  insert into public.voice_session_events(mission_id,session_id,kind,event_key,payload)values(p_mission,p_session,p_kind,p_key,p_payload)on conflict(session_id,event_key)do nothing returning id into v_id;
  if p_kind='fact'and v_id is not null then perform public.append_evidence(p_mission,'supply','verbal_terms','claimed',p_payload,'document','voice:'||p_session::text);end if;
  if p_kind='optout'and v_id is not null then insert into public.counterparty_optouts(mission_id,counterparty_id,source)values(p_mission,v.counterparty_id,'voice:'||p_session::text)on conflict(counterparty_id)do nothing;end if;
  if p_kind='ended'and v_id is not null then
    insert into public.commitments(mission_id,party_id,direction,description,due_at,actor_id)values(p_mission,v.counterparty_id,'outbound','Send written confirmation of the call; verbal terms remain claimed until acknowledged.',clock_timestamp()+interval '15 minutes',private.actor_id())returning id into v_commitment;
    insert into public.commitment_states(mission_id,commitment_id,status)values(p_mission,v_commitment,'open');
    insert into public.voice_confirmation_obligations(session_id,mission_id,commitment_id)values(p_session,p_mission,v_commitment);
    insert into public.outbox(mission_id,type,payload)values(p_mission,'call.ended',jsonb_build_object('sessionId',p_session,'confirmationDueAt',clock_timestamp()+interval '15 minutes'));
  end if;return v_id;
end$$;
create function public.plan_voice_confirmation(p_mission uuid,p_session uuid,p_hash text,p_draft uuid default null)returns void language plpgsql security definer set search_path=''as $$declare v public.voice_sessions;prior text;content jsonb;approved boolean:=false;begin
 perform private.require_role(array['policy_role']);perform private.lock_mission(p_mission);select*into strict v from public.voice_sessions where mission_id=p_mission and id=p_session;
 if p_hash!~'^[a-f0-9]{64}$'or not exists(select from public.voice_confirmation_obligations where mission_id=p_mission and session_id=p_session)or not exists(select from public.voice_session_events where session_id=p_session and kind='ended')then raise exception 'validation: ended call and confirmation obligation required';end if;
 if p_draft is not null then select a.content into strict content from public.artifact_versions a where a.mission_id=p_mission and a.id=p_draft;approved:=private.readiness_current_approved(p_mission,p_draft);
  if content->'effectIntent'->>'action'<>'send_message'or content->'effectIntent'->>'counterpartyId'<>v.counterparty_id::text or content->'payload'->>'channel'<>'email'or encode(public.digest(content->'payload'->>'text','sha256'),'hex')<>p_hash then raise exception 'validation: confirmation draft body or counterparty differs';end if;
  insert into public.voice_confirmation_drafts(mission_id,session_id,artifact_version_id)values(p_mission,p_session,p_draft)on conflict(artifact_version_id)do nothing;
 end if;
 select body_hash into prior from private.voice_confirmation_payloads where session_id=p_session;
 if prior is not null and prior<>p_hash and not approved then raise exception 'needs_approval: confirmation revision requires a current reviewed draft';end if;
 insert into private.voice_confirmation_payloads(session_id,mission_id,body_hash)values(p_session,p_mission,p_hash)on conflict(session_id)do update set body_hash=excluded.body_hash;
end$$;
create function private.voice_confirmation_close_guard()returns trigger language plpgsql security definer set search_path=''as $$begin
 if new.status='closed'and exists(select from public.voice_confirmation_obligations where mission_id=new.mission_id and commitment_id=new.commitment_id)and not exists(
  select from public.voice_confirmation_obligations o join public.voice_sessions v on v.id=o.session_id join private.voice_confirmation_payloads expected on expected.session_id=v.id
  join public.evidence e on e.id=new.closed_by_evidence_id and e.mission_id=o.mission_id and e.kind='voice_written_confirmation'and e.trust='performed'and e.payload->>'sessionId'=v.id::text
  join public.provider_receipts r on r.id=e.provider_receipt_id and r.mission_id=o.mission_id and r.provider='resend'and r.operation='send_message'
  join public.messages m on m.receipt_id=r.id and m.mission_id=o.mission_id and m.direction='outbound'and m.channel='email'
  join public.threads t on t.id=m.thread_id and t.counterparty_id=v.counterparty_id
  where o.mission_id=new.mission_id and o.commitment_id=new.commitment_id and encode(public.digest(m.original,'sha256'),'hex')=expected.body_hash
 )then raise exception 'invariant_violation: call confirmation closes only on its real written-message receipt';end if;return new;
end$$;
create trigger voice_confirmation_close_guard before insert on public.commitment_states for each row execute function private.voice_confirmation_close_guard();
create function public.complete_voice_confirmation(p_mission uuid,p_session uuid,p_receipt uuid)returns uuid language plpgsql security definer set search_path=''as $$declare commitment uuid;fact uuid;begin
 perform private.require_role(array['policy_role']);perform private.lock_mission(p_mission);
 select o.commitment_id into strict commitment from public.voice_confirmation_obligations o join public.voice_sessions v on v.id=o.session_id join private.voice_confirmation_payloads expected on expected.session_id=v.id
 join public.provider_receipts r on r.id=p_receipt and r.mission_id=o.mission_id and r.provider='resend'and r.operation='send_message'
 join public.messages m on m.receipt_id=r.id and m.mission_id=o.mission_id and m.direction='outbound'and m.channel='email'join public.threads t on t.id=m.thread_id and t.counterparty_id=v.counterparty_id
 where o.mission_id=p_mission and o.session_id=p_session and encode(public.digest(m.original,'sha256'),'hex')=expected.body_hash;
 select closed_by_evidence_id into fact from public.commitment_states where mission_id=p_mission and commitment_id=commitment and status='closed'limit 1;if fact is not null then return fact;end if;
 fact:=public.append_evidence(p_mission,'supply','voice_written_confirmation','performed',jsonb_build_object('sessionId',p_session,'commitmentId',commitment),'receipt',p_receipt::text,p_receipt);perform public.close_commitment(p_mission,commitment,fact);
 insert into public.voice_session_events(mission_id,session_id,kind,event_key,payload)values(p_mission,p_session,'followup','written-confirmation',jsonb_build_object('status','sent','receiptId',p_receipt,'evidenceId',fact))on conflict(session_id,event_key)do nothing;return fact;
end$$;
create function public.reconcile_voice_confirmations(p_mission uuid)returns integer language plpgsql security definer set search_path=''as $$declare item record;done integer:=0;begin
 perform private.require_role(array['policy_role']);perform private.lock_mission(p_mission);
 for item in select distinct o.session_id,m.receipt_id from public.voice_confirmation_obligations o join public.voice_sessions v on v.id=o.session_id join private.voice_confirmation_payloads expected on expected.session_id=v.id join public.threads t on t.mission_id=o.mission_id and t.counterparty_id=v.counterparty_id join public.messages m on m.mission_id=o.mission_id and m.thread_id=t.id and m.direction='outbound'and m.channel='email'and m.receipt_id is not null where o.mission_id=p_mission and encode(public.digest(m.original,'sha256'),'hex')=expected.body_hash and not exists(select from public.commitment_states cs where cs.commitment_id=o.commitment_id and cs.status='closed')loop perform public.complete_voice_confirmation(p_mission,item.session_id,item.receipt_id);done:=done+1;end loop;return done;
end$$;
revoke all on function private.voice_confirmation_close_guard()from public;
revoke all on function public.plan_voice_confirmation(uuid,uuid,text,uuid),public.complete_voice_confirmation(uuid,uuid,uuid),public.reconcile_voice_confirmations(uuid)from public;
grant execute on function public.plan_voice_confirmation(uuid,uuid,text,uuid),public.complete_voice_confirmation(uuid,uuid,uuid),public.reconcile_voice_confirmations(uuid)to policy_role;

create or replace function public.register_payment_refund(p_mission uuid,p_receipt uuid)returns uuid language plpgsql security definer set search_path=''as $$declare r public.provider_receipts;a public.effect_authorizations;p public.payments;v_id uuid;v_sum bigint;begin
  perform private.require_role(array['policy_role']);perform private.lock_mission(p_mission);select *into strict r from public.provider_receipts where mission_id=p_mission and id=p_receipt and provider='paypal'and operation='payment_refund';select *into strict a from public.effect_authorizations where mission_id=p_mission and id=r.authorization_id and approval_id is not null;
  select pmt.*into strict p from public.payments pmt join public.payment_states captured on captured.payment_id=pmt.id and captured.state='captured'join public.provider_receipts original on original.id=captured.receipt_id where pmt.mission_id=p_mission and pmt.provider='paypal'and original.provider_reference=r.data->>'captureId'and original.data->>'orderId'=r.data->>'orderId'and pmt.payee_id=(a.intent->>'counterpartyId')::uuid and pmt.currency=a.intent->>'currency'and pmt.sandbox_mode=r.sandbox_mode;
  select id into v_id from public.payment_refunds where mission_id=p_mission and receipt_id=p_receipt;if v_id is not null then return v_id;end if;
  select coalesce(sum(amount_minor),0)into v_sum from public.payment_refunds where payment_id=p.id;if (a.intent->>'amountMinor')::bigint<=0 or (a.intent->>'amountMinor')::bigint+v_sum>p.amount_minor then raise exception 'invariant_violation: refund exceeds original payment';end if;
  insert into public.payment_refunds(mission_id,payment_id,authorization_id,receipt_id,provider_refund_id,amount_minor,currency,sandbox_mode)values(p_mission,p.id,a.id,r.id,r.provider_reference,(a.intent->>'amountMinor')::bigint,p.currency,p.sandbox_mode)returning id into v_id;return v_id;
end$$;-- Shopify mutation replies identify the affected resource, which can be
-- changed by several separately authorized operations. Native payment/message
-- transaction IDs remain globally deduplicated.
do $$declare constraint_name text;begin select c.conname into constraint_name from pg_constraint c where c.conrelid='public.provider_receipts'::regclass and c.contype='u'and pg_get_constraintdef(c.oid)='UNIQUE (provider, provider_reference, operation, sandbox_mode)';if constraint_name is not null then execute format('alter table public.provider_receipts drop constraint %I',constraint_name);end if;end$$;
create unique index provider_transaction_once on public.provider_receipts(provider,provider_reference,operation,sandbox_mode)where provider<>'shopify';
create function public.record_store_outcome(p_mission uuid,p_receipt uuid)returns uuid language plpgsql security definer set search_path=''as $$declare r public.provider_receipts;a public.effect_authorizations;v_payload jsonb;v_kind text;v_trust text;fact uuid;version uuid;decision uuid;approval_decision uuid;begin
 perform private.require_role(array['policy_role']);perform private.lock_mission(p_mission);select*into strict r from public.provider_receipts where mission_id=p_mission and id=p_receipt and provider='shopify';select*into strict a from public.effect_authorizations where mission_id=p_mission and id=r.authorization_id;version:=(a.intent->>'artifactVersionId')::uuid;perform private.check_version(p_mission,version);
 select coalesce(content->'payload',content)into strict v_payload from public.artifact_versions where mission_id=p_mission and id=version;
 if r.operation='store_publish'and r.data->>'verifiedKind'='store_published'and r.data->>'verifiedOutcome'='commerce'and r.data->>'verificationMethod'='verified_poll'and r.data->>'verifiedArtifactVersionId'=version::text then v_kind:='store_published';v_trust:='verified';
 elsif r.operation='store_publish_shipping'and v_payload->>'kind'='shipping'and exists(select from public.evidence e where e.mission_id=p_mission and e.id::text=v_payload->>'quoteEvidenceId'and e.trust in('verified','founder_confirmed')and not exists(select from public.stale_marks st where st.mission_id=p_mission and st.node_id=e.id)and not exists(select from public.evidence newer where newer.mission_id=p_mission and newer.supersedes_id=e.id))then v_kind:='shipping_configured';v_trust:='performed';
 elsif r.operation='store_configure'and v_payload->>'kind'in('product','page')then v_kind:='store_draft_created';v_trust:='performed';
 elsif r.operation='store_publish_policy'then v_kind:='store_policy_published';v_trust:='performed';
 elsif r.operation='store_test_order'and r.sandbox_mode then v_kind:='admin_test_order_refunded';v_trust:='performed';
 else raise exception 'validation: receipt has no supported store outcome';end if;
 select id into fact from public.evidence where mission_id=p_mission and provider_receipt_id=r.id and evidence.kind=v_kind;if fact is not null then return fact;end if;
 select decision_id into decision from public.artifact_statuses where mission_id=p_mission and artifact_version_id=version order by created_at desc,id desc limit 1;select decision_id into approval_decision from public.approvals where id=a.approval_id;
 if approval_decision is not null and not exists(select from public.active_decisions where mission_id=p_mission and id=approval_decision)then raise exception 'needs_approval: publication decision is no longer current';end if;
 fact:=public.append_evidence(p_mission,'commerce',v_kind,v_trust,jsonb_build_object('provider','shopify','resourceId',r.provider_reference,'artifactVersionId',version,'method',case when v_trust='verified'then'verified_poll'else'provider_receipt'end,'checkoutUiVerified',false,'emailDeliveryVerified',false),'receipt',r.id::text,r.id);
 insert into public.dependencies(mission_id,upstream_id,dependent_id,reason)values(p_mission,version,fact,'store outcome approved source'),(p_mission,decision,fact,'store outcome source approval')on conflict do nothing;
 if v_kind='shipping_configured'then insert into public.dependencies(mission_id,upstream_id,dependent_id,reason)values(p_mission,(v_payload->>'quoteEvidenceId')::uuid,fact,'confirmed shipping rate source')on conflict do nothing;end if;
 if approval_decision is not null then insert into public.dependencies(mission_id,upstream_id,dependent_id,reason)values(p_mission,approval_decision,fact,'store effect specific approval')on conflict do nothing;end if;return fact;
end$$;
revoke all on function public.record_store_outcome(uuid,uuid)from public;
grant execute on function public.record_store_outcome(uuid,uuid)to policy_role;

create or replace function private.check_version(p_mission uuid,p_version uuid)returns void language plpgsql stable set search_path='' as $$declare shipping jsonb;begin
  if p_version is null then return;end if;
  -- Typed proformas reference the approved spec even when a model omitted derivedFrom.
  -- UNION deduplicates cycles; every referenced node still must be current and approved.
  if exists(with recursive refs(id)as(select p_version union select(v.content#>>'{proformaInvoice,specVersionId}')::uuid from public.artifact_versions v join refs r on r.id=v.id where v.mission_id=p_mission and v.content#>>'{proformaInvoice,specVersionId}'is not null)
    select from refs r left join public.artifact_versions v on v.id=r.id and v.mission_id=p_mission left join public.artifacts a on a.id=v.artifact_id and a.mission_id=p_mission
    left join lateral(select s.*from public.artifact_statuses s where s.mission_id=p_mission and s.artifact_version_id=v.id order by s.created_at desc,s.id desc limit 1)s on true
    where v.id is null or(r.id<>p_version and a.outcome<>'product')or exists(select from public.artifact_versions n where n.artifact_id=v.artifact_id and n.version_no>v.version_no)or exists(select from public.stale_marks d where d.mission_id=p_mission and d.node_id=v.id)
    or s.status is distinct from 'approved'or not exists(select from public.decision_resolutions d where d.mission_id=p_mission and d.decision_id=s.decision_id and d.response in('approve','choose'))or exists(select from public.decision_supersessions d where d.mission_id=p_mission and d.previous_id=s.decision_id)or exists(select from public.stale_marks d where d.mission_id=p_mission and d.node_id=s.decision_id))then raise exception 'needs_approval: artifact version stale or not approved (including referenced specification)';end if;
  select coalesce(content->'payload',content)into shipping from public.artifact_versions where mission_id=p_mission and id=p_version;
  if shipping->>'kind'='shipping'and not exists(select from public.evidence e where e.mission_id=p_mission and e.id::text=shipping->>'quoteEvidenceId'and e.kind='shipping_rate_confirmed'and e.trust in('verified','founder_confirmed')and e.payload->'rate'->>'currency'=shipping->>'currency'and e.payload->'rate'->>'countryCode'=shipping->>'countryCode'and jsonb_typeof(e.payload->'rate'->'amountMinor')='number'and(e.payload->'rate'->>'amountMinor')::numeric>0 and not exists(select from public.stale_marks st where st.mission_id=p_mission and st.node_id=e.id)and not exists(select from public.evidence newer where newer.mission_id=p_mission and newer.supersedes_id=e.id))then raise exception 'needs_approval: current confirmed carrier quote currency and country required';end if;
end$$;
revoke all on function private.mandate_exposure(uuid,uuid),private.mission_exposure(uuid),private.payment_source(uuid,jsonb,uuid)from public;
revoke all on function public.register_payment_authorization(uuid,uuid),public.payment_for_capture(uuid,uuid),public.register_authorization_void(uuid,uuid)from public;
grant execute on function public.register_payment_authorization(uuid,uuid),public.payment_for_capture(uuid,uuid),public.register_authorization_void(uuid,uuid)to policy_role;
create or replace view public.money_totals with(security_invoker=true)as select mission_id,currency,sandbox_mode,coalesce(sum(amount_minor)filter(where kind='spent'),0)as spent_minor,coalesce(sum(amount_minor)filter(where kind='refund'),0)as refund_minor,coalesce(sum(amount_minor)filter(where kind='forecast'and(not exists(select from public.financial_plans f where f.mission_id=money_ledger.mission_id)or ref_id=public.current_financial_plan(mission_id))),0)as forecast_minor,coalesce(sum(amount_minor)filter(where kind='committed'and not exists(select from public.payments p join public.payment_authorizations pa on pa.payment_id=p.id join public.authorization_followups f on f.source_authorization_id=pa.id and f.action='payment_authorization_void'join public.provider_receipts r on r.authorization_id=f.effect_authorization_id and r.operation='payment_authorization_void'join public.payment_states ps on ps.payment_id=p.id and ps.state='failed'and ps.receipt_id=r.id where p.mission_id=money_ledger.mission_id and p.id=money_ledger.ref_id)and not exists(select from public.money_ledger paid where paid.mission_id=money_ledger.mission_id and paid.ref_id=money_ledger.ref_id and paid.kind='spent')),0)as committed_minor from public.money_ledger group by mission_id,currency,sandbox_mode;
commit;
